fp15_fahrstrasse.FB_Fahrstrasse:
FUNCTION_BLOCK "FB_Fahrstrasse"
VAR_INPUT
   Anforderung : Bool;
   Zug_durch : Bool;   // Zug hat Fahrstrasse verlassen
   Sicher_OK : Bool;
END_VAR
VAR_OUTPUT
   Ruhe : Bool;
   Weiche_laeuft : Bool;
   Fahrt : Bool;
   Halt : Bool;
END_VAR
VAR_IN_OUT
   Zuege : Int;   // Zugzähler
END_VAR
VAR
   Schritt_Ruhe : Bool;
   Schritt_Stellen : Bool;
   Schritt_Fahrt : Bool;
   T_Stellen : TON;
END_VAR
BEGIN
NETWORK Grundstellung
NOT #Schritt_Ruhe AND NOT #Schritt_Stellen AND NOT #Schritt_Fahrt => S #Schritt_Ruhe;

NETWORK Ruhe -> Stellen
#Schritt_Ruhe AND #Anforderung AND #Sicher_OK => S #Schritt_Stellen, R #Schritt_Ruhe;

NETWORK Stellen -> Fahrt
#Schritt_Stellen AND TON(#T_Stellen, T#2S) => S #Schritt_Fahrt, R #Schritt_Stellen, INC(#Zuege);

NETWORK Fahrt -> Ruhe
#Schritt_Fahrt AND #Zug_durch => S #Schritt_Ruhe, R #Schritt_Fahrt;

NETWORK Sicherung weg
NOT #Sicher_OK AND (#Schritt_Stellen OR #Schritt_Fahrt) => S #Schritt_Ruhe, R #Schritt_Stellen, R #Schritt_Fahrt;

NETWORK Ruhe
#Schritt_Ruhe => #Ruhe, #Halt;

NETWORK Weiche stellen
#Schritt_Stellen => #Weiche_laeuft;

NETWORK Fahrt
#Schritt_Fahrt => #Fahrt;
END_FUNCTION_BLOCK

